import java.util.*;

// A simplified geohash-based index mapping cell prefixes to the drivers
// currently located within them, supporting an expanding search radius.
public class GeohashIndex {
    private final Map<String, Set<String>> cellToDrivers = new HashMap<>();
    private final Map<String, String> driverToCell = new HashMap<>();

    public void updateDriverLocation(String driverId, String geohashCell) {
        String previousCell = driverToCell.get(driverId);
        if (previousCell != null) {
            cellToDrivers.getOrDefault(previousCell, Collections.emptySet()).remove(driverId);
        }
        cellToDrivers.computeIfAbsent(geohashCell, k -> new HashSet<>()).add(driverId);
        driverToCell.put(driverId, geohashCell);
    }

    public Set<String> findDriversInCell(String cell) {
        return cellToDrivers.getOrDefault(cell, Collections.emptySet());
    }
}

