    map<string, string> driverToCell;

public:
    void updateDriverLocation(string driverId, string geohashCell) {
        auto it = driverToCell.find(driverId);
        if (it != driverToCell.end()) {
            cellToDrivers[it->second].erase(driverId);
        }
        cellToDrivers[geohashCell].insert(driverId);
        driverToCell[driverId] = geohashCell;
    }

    set<string> findDriversInCell(string cell) {
        return cellToDrivers.count(cell) ? cellToDrivers[cell] : set<string>();
    }
