import java.util.*;

// Searches outward from a rider's cell, one ring of neighboring cells at a
// time, until enough candidate drivers are found or a max radius is hit.
public class DriverMatchingService {
    private final GeohashIndex index;
    private final int maxRingExpansions;

    public DriverMatchingService(GeohashIndex index, int maxRingExpansions) {
        this.index = index;
        this.maxRingExpansions = maxRingExpansions;
    }

    public List<String> findCandidates(String riderCell, int minCandidates) {
        List<String> candidates = new ArrayList<>();
        List<String> ring = new ArrayList<>(List.of(riderCell));
        int expansions = 0;
        while (candidates.size() < minCandidates && expansions <= maxRingExpansions) {
            for (String cell : ring) {
                candidates.addAll(index.findDriversInCell(cell));
            }
            ring = neighborCells(ring);
            expansions++;
        }
        return candidates;
    }

    private List<String> neighborCells(List<String> currentRing) {
        // In production this computes the actual adjacent geohash cells;
        // simplified here since the neighbor math is geohash library specific.
        return new ArrayList<>();
    }
}

