import java.util.*;

// Enforces that a trip only ever moves through valid state transitions,
// rejecting anything that would represent an inconsistent trip lifecycle.
public class TripStateMachine {
    public enum TripStatus { REQUESTED, MATCHED, EN_ROUTE, STARTED, COMPLETED, CANCELLED }

    private static final Map<TripStatus, Set<TripStatus>> VALID_TRANSITIONS = Map.of(
        TripStatus.REQUESTED, Set.of(TripStatus.MATCHED, TripStatus.CANCELLED),
        TripStatus.MATCHED, Set.of(TripStatus.EN_ROUTE, TripStatus.CANCELLED),
        TripStatus.EN_ROUTE, Set.of(TripStatus.STARTED),
        TripStatus.STARTED, Set.of(TripStatus.COMPLETED)
    );

    public boolean canTransition(TripStatus from, TripStatus to) {
        return VALID_TRANSITIONS.getOrDefault(from, Set.of()).contains(to);
    }

    public TripStatus transition(TripStatus current, TripStatus target) {
        if (!canTransition(current, target)) {
            throw new IllegalStateException("Invalid transition from " + current + " to " + target);
        }
        return target;
    }
}

