#include <map>
#include <set>
#include <stdexcept>

enum class TripStatus { REQUESTED, MATCHED, EN_ROUTE, STARTED, COMPLETED, CANCELLED };

// Enforces that a trip only ever moves through valid state transitions,
// rejecting anything that would represent an inconsistent trip lifecycle.
class TripStateMachine {
public:
    bool canTransition(TripStatus from, TripStatus to) {
        auto it = validTransitions().find(from);
        if (it == validTransitions().end()) return false;
        return it->second.count(to) > 0;
    }

    TripStatus transition(TripStatus current, TripStatus target) {
        if (!canTransition(current, target)) throw std::invalid_argument("Invalid transition");
        return target;
    }

private:
    static const std::map<TripStatus, std::set<TripStatus>>& validTransitions() {
        static const std::map<TripStatus, std::set<TripStatus>> table = {
            { TripStatus::REQUESTED, { TripStatus::MATCHED, TripStatus::CANCELLED } },
            { TripStatus::MATCHED, { TripStatus::EN_ROUTE, TripStatus::CANCELLED } },
            { TripStatus::EN_ROUTE, { TripStatus::STARTED } },
            { TripStatus::STARTED, { TripStatus::COMPLETED } },
        };
        return table;
    }
};

