class TripStatus(Enum):
    REQUESTED = "requested"
    MATCHED = "matched"
    EN_ROUTE = "en_route"
    STARTED = "started"
    COMPLETED = "completed"
    CANCELLED = "cancelled"


# Enforces that a trip only ever moves through valid state transitions,
# rejecting anything that would represent an inconsistent trip lifecycle.
class TripStateMachine:
    _VALID_TRANSITIONS: Dict[TripStatus, Set[TripStatus]] = {
        TripStatus.REQUESTED: {TripStatus.MATCHED, TripStatus.CANCELLED},
        TripStatus.MATCHED: {TripStatus.EN_ROUTE, TripStatus.CANCELLED},
        TripStatus.EN_ROUTE: {TripStatus.STARTED},
        TripStatus.STARTED: {TripStatus.COMPLETED},
    }

    def can_transition(self, frm: TripStatus, to: TripStatus) -> bool:
        return to in self._VALID_TRANSITIONS.get(frm, set())

    def transition(self, current: TripStatus, target: TripStatus) -> TripStatus:
        if not self.can_transition(current, target):
            raise ValueError(f"Invalid transition from {current} to {target}")
        return target

